args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?dboBirth ?dbpBirth WHERE {
  VALUES ?person { dbr:Louise_of_Hesse-Kassel dbr:Viktor_Šiljeg }
  OPTIONAL { ?person dbo:birthDate ?dboBirth . }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth . }
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(langMatches(lang(?personLabel), "EN")) }
}

PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label ?birthDate WHERE {
  VALUES ?person { dbr:Louise_of_Hesse-Kassel dbr:Viktor_Šiljeg }
  OPTIONAL { ?person dbp:birthDate ?birthDate }
  OPTIONAL { ?person rdfs:label ?label . FILTER(langMatches(lang(?label), "EN")) }
} ORDER BY ?person

